-- Fonctions originales Setup Assist. Données : voir LICENSE-DATA.txt.
local R = Relais

local function Read(api, ...)
    if type(api) ~= "function" then return nil end
    local ok, value = pcall(api, ...)
    if ok then return value end
end

local function FormatName(value)
    if type(value) ~= "string" or value == "" then return nil end
    if type(zo_strformat) == "function" then
        local formatted = Read(zo_strformat, "<<1>>", value)
        if type(formatted) == "string" and formatted ~= "" then value = formatted end
    end
    return value:gsub("%^[%a]+", ""):gsub("[\r\n]", " ")
end

local function CleanSpaces(value)
    return value:gsub("%s+", " "):gsub("^%s+", ""):gsub("%s+$", "")
end

local function NormalizeName(value)
    value = FormatName(value)
    if not value then return nil end
    value = CleanSpaces(value)
    local lowered = Read(zo_strlower, value)
    return type(lowered) == "string" and lowered or string.lower(value)
end

local function Copy(value)
    if type(value) ~= "table" then return value end
    local result = {}
    for key, item in pairs(value) do result[key] = Copy(item) end
    return result
end

local function Set(entry, key, value)
    if value ~= nil and entry[key] ~= value then entry[key] = value; return true end
    return false
end

local function AddUnique(values, value)
    for _, existing in ipairs(values) do if existing == value then return false end end
    values[#values + 1] = value
    return true
end

R.ContentCatalog = { apiVersion = 101051, verifiedAt = "2026-10-03", revision = 1, entries = {},
    dataLicense = "CC-BY-SA-2.5", unknownBossAliasesAreEmpty = true,
    source = "ESO API 101051 : GetActivityZoneId / GetActivityName ; UESP (rencontres)" }

for _, template in ipairs(CONTENT_TEMPLATES) do
    local entry = Copy(template)
    entry.name = entry.nameFr or entry.nameEn
    entry.zoneIds = { entry.zoneId }
    entry.namesByLocale = entry.namesByLocale or { en = entry.nameEn }
    entry.activityIds = {}
    entry.zoneIdentityVerifiedInGame = false
    R.ContentCatalog.entries[#R.ContentCatalog.entries + 1] = entry
end

-- Les trois listes natives contiennent aussi les activités verrouillées pour
-- le compte. Aucun filtre de DLC, niveau, abonnement ou difficulté n'est appliqué.
-- Un appel ultérieur complète la même table ; les IDs des setups restent stables.
function R:InitializeContentCatalog()
    local catalog = self.ContentCatalog
    local changed = self.InitializeRaidRouteEncounters and self:InitializeRaidRouteEncounters() or false
    local byId = {}
    local locale = Read(GetCVar, "language.2")
    if type(locale) ~= "string" or locale == "" then locale = "unknown" end
    for _, entry in ipairs(catalog.entries) do
        byId[entry.id] = entry
        -- Les épreuves ne disposent pas nécessairement d'une activité LFG.
        -- Une égalité stricte ID -> nom natif et nom de référence de la même
        -- langue confirme le contenu sans accepter un nom de zone parent.
        -- Les événements restent exclus : leur nom existe hors de leur fenêtre.
        if not entry.eventContent and not entry.zoneIdentityVerifiedInGame then
            local expected = entry.namesByLocale[locale]
            if not expected and locale == "en" then expected = entry.nameEn end
            local expectedNormalized = NormalizeName(expected)
            if expectedNormalized and expectedNormalized ~= "" then
                local zoneName = FormatName(Read(GetZoneNameById, entry.zoneId))
                if NormalizeName(zoneName) == expectedNormalized then
                    zoneName = CleanSpaces(zoneName)
                    if Set(entry, "zoneIdentityVerifiedInGame", true) then changed = true end
                    if Set(entry, "zoneIdentityConfirmation", "nativeZoneName") then changed = true end
                    if Set(entry, "nativeZoneName", zoneName) then changed = true end
                    if Set(entry, "localizedName", zoneName) then changed = true end
                    if Set(entry, "localizedLanguage", locale) then changed = true end
                end
            end
        end
    end

    local types = {
        { activity = LFG_ACTIVITY_TRIAL, category = "trials" },
        { activity = LFG_ACTIVITY_DUNGEON, category = "dungeons", normal = true },
        { activity = LFG_ACTIVITY_MASTER_DUNGEON, category = "dungeons", veteran = true },
    }
    local complete = true
    local totalActivities = 0
    for _, activityType in ipairs(types) do
        local count = activityType.activity ~= nil and Read(GetNumActivitiesByType, activityType.activity) or nil
        if type(count) ~= "number" or count < 0 or count ~= math.floor(count) or count > 10000 then
            complete = false
        else
            totalActivities = totalActivities + count
            for index = 1, count do
                local activityId = Read(GetActivityIdByTypeAndIndex, activityType.activity, index)
                local zoneId = type(activityId) == "number" and Read(GetActivityZoneId, activityId) or nil
                local activityName = type(activityId) == "number" and FormatName(Read(GetActivityName, activityId)) or nil
                if type(zoneId) == "number" and zoneId > 0 and zoneId == math.floor(zoneId) and activityName then
                    local prefix = activityType.category == "trials" and "trial:" or "dungeon:"
                    local id = prefix .. tostring(zoneId)
                    local entry = byId[id]
                    if not entry then
                        entry = { id = id, category = activityType.category, zoneId = zoneId, zoneIds = { zoneId },
                            name = activityName, nameEn = locale == "en" and activityName or nil,
                            namesByLocale = {}, activityIds = {}, encounters = {},
                            difficulty = { hardMode = { detection = "manual", verified = false } },
                            sources = { "https://github.com/esoui/esoui/blob/6639eb2adecc0480557d9068579319919a0c3fe6/ESOUIDocumentation.txt" },
                            encounterCoverage = "unknown", orderVerified = false }
                        catalog.entries[#catalog.entries + 1] = entry
                        byId[id] = entry
                        changed = true
                    end
                    -- Le titre spécifique du chercheur d'activité est utilisé par
                    -- l'UI native. Le nom de zone peut désigner un espace parent.
                    local zoneName = FormatName(Read(GetZoneNameById, zoneId))
                    if Set(entry, "name", activityName) then changed = true end
                    if Set(entry, "localizedName", activityName) then changed = true end
                    if Set(entry, "localizedLanguage", locale) then changed = true end
                    if Set(entry.namesByLocale, locale, activityName) then changed = true end
                    if zoneName and Set(entry, "nativeZoneName", zoneName) then changed = true end
                    if locale == "en" and Set(entry, "nameEn", activityName) then changed = true end
                    if AddUnique(entry.activityIds, activityId) then changed = true end
                    if Set(entry, "zoneIdentityVerifiedInGame", true) then changed = true end
                    if Set(entry, "zoneIdentityConfirmation", "nativeActivity") then changed = true end
                    if activityType.normal and Set(entry.difficulty, "normal", true) then changed = true end
                    if activityType.veteran and Set(entry.difficulty, "veteran", true) then changed = true end
                    local collectibleId = Read(GetRequiredActivityCollectibleId, activityId)
                    if type(collectibleId) == "number" and collectibleId >= 0 then
                        entry.requiredCollectibleIds = entry.requiredCollectibleIds or {}
                        if AddUnique(entry.requiredCollectibleIds, collectibleId) then changed = true end
                        -- Ce champ décrit l'accès actuel, pas l'histoire commerciale du contenu.
                        if collectibleId > 0 and Set(entry, "requiresCollectible", true) then changed = true end
                    end
                else
                    complete = false
                end
            end
        end
    end
    if totalActivities == 0 then complete = false end
    if Set(catalog, "nativeEnumerationComplete", complete) then changed = true end
    if changed then catalog.revision = catalog.revision + 1 end
    return catalog, changed
end
